import{z as B,x as A,o as l,c as p,q as t,j as s,D as E,d as e,s as o,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Easley–O’Hara 事件不确定","description":"","frontmatter":{"title":"Easley–O’Hara 事件不确定","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/easley-ohara-event.md","filePath":"quant/easley-ohara-event.md","lastUpdated":1791413859000}'),d={name:"quant/easley-ohara-event.md"};function h(m,a,u,c,D,f){const n=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="easley–o-hara-事件不确定" tabindex="-1">Easley–O’Hara 事件不确定 <a class="header-anchor" href="#easley–o-hara-事件不确定" aria-label="Permalink to &quot;Easley–O’Hara 事件不确定&quot;">​</a></h1><div class="epigraph"><p>做市商不仅不知道消息是好是坏，往往也不知道今天究竟有没有私有信息事件。没有事件时，买卖都是噪声；有事件时，方向才携带关于价值的证据。</p><footer>—— Easley and O&#39;Hara, Time and the Process of Security Price Adjustment, Journal of Finance, 1992</footer></div><p><a href="/quant/back-continuous-insider">Back</a>与多期 Kyle 都假定知情者<strong>已经持有</strong>一条关于 \\(V\\) 的信息，不确定只在数值与何时写入价格。缺口是第二层不确定：公众连「今天是否发生了信息事件」都不知道。Easley 与 O&#39;Hara（1992）把事件发生与否写进学习；方向序列因此有时有信号、有时全是噪声。本课不重做<a href="/quant/pin">PIN</a> 的日度泊松极大似然——那是 1996 年 EKOP 的估计装置。这里只补理论：事件不确定如何改变报价调整的时间形态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Glosten-Milgrom 的标准二叉树里，每期都以固定概率碰到知情者。若某些日子根本没有私有信息，知情到达率为零，买卖方向不应移动信念。做市商事先分不清「无事件的热闹噪声日」与「有事件但尚未暴露的日子」。于是学习必须在两个假设之间分配后验：\\(\\alpha\\) 为事件发生概率，事件内再分好坏消息。问题是：成交的时间模式——不只是最近一笔的方向——如何同时更新「有没有事件」与「若有，是哪一种」。</p><p>事件不确定还会产生<strong>无交易也是信号</strong>。若有知情者，他们会积极交易；长时间没有成交，更像没有事件，报价应朝无条件期望收拢、价差收窄。这与「没成交所以什么也没学到」相反。</p><p><span class="marginnote">把做市商想成只能看成交记录的侦探：他同时握着三个假设——今天没案子、有人知道好消息、有人知道坏消息。每笔主动买卖是一份口供，每段长时间沉默也是证词：迟迟没人报案，多半今天本来就没有案子。</span></p><h3 id="与-pin-估计课的分工" tabindex="-1">与 PIN 估计课的分工 <a class="header-anchor" href="#与-pin-估计课的分工" aria-label="Permalink to &quot;与 PIN 估计课的分工&quot;">​</a></h3><p><a href="/quant/pin">PIN</a> 把 \\(\\alpha,\\mu,\\varepsilon\\) 收成日度 \\((B,S)\\) 计数的似然，输出一个概率数字。本课停留在序贯信念：每一笔（以及每一段沉默）如何改写事件后验。不要在这里重写 EKOP 似然，也不要把 PIN 高读成连续 Kyle 的 \\(\\lambda\\) 大。</p><p><span class="marginnote">Easley–O&#39;Hara（1987）处理的是交易规模也携带信息；1992 年这篇的关键新增是时间与事件不确定。规模与事件是两层，不要合成「EO 模型」一个黑箱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一个可计算的树：每个交易日开始，以概率 \\(\\alpha\\) 发生事件；发生则价值取高或低。知情者只在有事件时按方向交易；非知情者无论有无事件都可能因流动性买卖，也可能不来。做市商的状态是后验 \\((\\pi_{\\mathrm{no}},\\pi_{\\mathrm{up}},\\pi_{\\mathrm{down}})\\)。一笔主动买提高「有好消息」的权重，也提高「有事件」的权重；一笔卖对称。一段无交易提高「无事件」的权重。</p><p>买卖报价仍是下一笔方向条件下的价值期望，与 Glosten-Milgrom 同构，但条件概率现在对三个体制求和。价差在「事件后验高、好坏尚未分清」时最宽；在「几乎肯定无事件」或「几乎肯定已经是某一边」时变窄。</p><p><span class="marginnote">直觉理解价差宽度：设事件先验 \\(\\alpha=0.5\\)、好坏各半。开盘时「有事件但方向未明」的概率质量最大，价差最宽；连续几笔主动买之后，好坏后验逐渐分开，不确定减少，价差随之收窄——价差宽度其实是在为三层后验的总不确定性标价。</span></p><h3 id="调整速度不是常数" tabindex="-1">调整速度不是常数 <a class="header-anchor" href="#调整速度不是常数" aria-label="Permalink to &quot;调整速度不是常数&quot;">​</a></h3><p>有事件且知情交易密集时，方向很快分开好坏，价格跳到位。无事件时，同样密集的噪声买卖会暂时把后验往有事件推，随后若方向来回抵消，事件后验再退回来——价格出现一段随后被纠正的漂移。时间本身成为状态：开盘后前几笔的信息含量，依赖于先验 \\(\\alpha\\)，而不是一个全日常数。</p>',16)),(l(),s(i,null,{default:E(()=>[o(n,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%88%E9%AA%8C%3A%20%E6%9C%89%E6%97%A0%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20Trade%5B%22%E6%88%90%E4%BA%A4%E6%88%96%E6%B2%89%E9%BB%98%22%5D%0A%20%20Trade%20--%3E%20Ev%5B%22%E6%9B%B4%E6%96%B0%E4%BA%8B%E4%BB%B6%E5%90%8E%E9%AA%8C%22%5D%0A%20%20Trade%20--%3E%20Dir%5B%22%E6%9B%B4%E6%96%B0%E5%A5%BD%E5%9D%8F%E5%90%8E%E9%AA%8C%22%5D%0A%20%20Ev%20--%3E%20Q%5B%22bid%20%2F%20ask%20%3D%20%E6%96%B9%E5%90%91%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20Dir%20--%3E%20Q%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("事件不确定把「噪声」从一种人改写成一种"),r("strong",null,"日子"),e("。无事件日里所有人都是非知情的，订单流的不平衡是纯粹的流动性；做市商若把这类不平衡当成 Kyle 式信号，会过度移动价格。有事件日里不平衡才是证据。市场质量在两类日子之间切换：同样的买卖比，在高 \\(\\alpha\\) 股票上更像信息，在低 \\(\\alpha\\) 股票上更像噪声。这与低频股 PIN 识别的经济动机相接，但机制在逐笔后验里已经完成。")],-1)),(l(),s(i,null,{default:E(()=>[o(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUY%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E4%B8%BB%E5%8A%A8%E4%B9%B0%22%5D%20--%3E%20Q%7B%22%E4%BD%93%E5%88%B6%E5%90%8E%E9%AA%8C%E8%90%BD%E5%9C%A8%E5%93%AA%22%7D%0A%20%20Q%20--%20%22%E5%87%A0%E4%B9%8E%E8%82%AF%E5%AE%9A%E6%97%A0%E4%BA%8B%E4%BB%B6%22%20--%3E%20N%5B%22%E5%A4%9A%E4%B8%BA%E6%B5%81%E5%8A%A8%E6%80%A7%E5%99%AA%E5%A3%B0%3A%20%E6%8A%A5%E4%BB%B7%E5%B0%91%E5%8A%A8%22%5D%0A%20%20Q%20--%20%22%E6%9C%89%E4%BA%8B%E4%BB%B6%E4%BD%86%E5%A5%BD%E5%9D%8F%E6%9C%AA%E5%88%86%22%20--%3E%20W%5B%22%E8%AF%81%E6%8D%AE%E8%A2%AB%E7%A8%80%E9%87%8A%3A%20%E4%BB%B7%E5%B7%AE%E6%9C%80%E5%AE%BD%22%5D%0A%20%20Q%20--%20%22%E5%A5%BD%E5%9D%8F%E5%B7%B2%E6%B8%90%E5%88%86%E6%B8%85%22%20--%3E%20D%5B%22%E6%96%B9%E5%90%91%E6%9D%83%E9%87%8D%E5%8F%A0%E5%8A%A0%3A%20%E4%BB%B7%E6%A0%BC%E8%BE%83%E5%BF%AB%E5%88%B0%E4%BD%8D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>无交易的信号价值依赖知情者是否必须交易。若知情者可以等待，沉默的解释变弱。1992 年模型对到达过程的规定，决定了「时间」有多强的信息含量。</p><p><span class="marginnote">常见误区：看到买入占优就断定有人知道好消息。在少有事件的低 \\(\\alpha\\) 股票上，同样的买卖失衡几乎全是流动性噪声；把噪声当信号，做市商会过度移动价格，反向策略吃的正是这种过度反应。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>事件在日初一次抽签、日内不再新抽，是强假设。真实公告可以在盘中到达，事件强度随日历变化。知情者人数与强度若内生，沉默的含义改变。连续时间滤波（Back）假定信息已存在；本课的不确定是离散体制。两者不要塞进同一个状态方程。</p><p>估计层用日度计数是压缩，会丢掉「无交易时段」的日内路径。要用本课机制做经验，需要标记交易时钟上的沉默，而不仅是全日 \\(B\\) 与 \\(S\\)。</p><p><span class="marginnote">把开盘宽价差只解释成隔夜库存，会漏掉事件不确定：隔夜可能积累了「有没有新闻」的先验，开盘前几笔同时在解这两层。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Easley–O&#39;Hara（1992）在好坏消息之外加入「有无信息事件」；学习对象是体制后验。</li><li>无交易可以是无事件的证据，报价向无条件期望收拢。</li><li>价差在事件未决时最宽，在无事件或已分清时变窄。</li><li>PIN 是这一结构的日度估计，本课不重写似然。</li><li>出处：Easley and O&#39;Hara, <em>Journal of Finance</em>, 1992；规模信息见同作者 1987 年 <em>Journal of Finance</em>；估计见 EKOP, <em>Journal of Finance</em>, 1996。</li></ul>',8))])}const b=B(d,[["render",h]]);export{P as __pageData,b as default};
